import os
import subprocess
from abc import abstractmethod, ABCMeta
from future.utils import with_metaclass
from taf.ul.ettf.config.secrets import secrets
from taf.ul.ettf.typed.custom_types import IsType
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.utils.tshark import Tshark
from taf.ul.ettf.logger import custom_logger

logger = custom_logger('Tjellyfish')


class ITJellyfishRemoteCommand(with_metaclass(ABCMeta)):
    @property
    @abstractmethod
    def cmd(self):
        pass


class TJellyfishRemoteCommand(ITJellyfishRemoteCommand):
    def __init__(self, command):
        self._cmd = str(command)

    @property
    def cmd(self):
        return self._cmd


class Tjellyfish(Tshark):

    PIPE = '-'

    def __init__(self):
        super(Tjellyfish, self).__init__()
        self._input_cmd = None
        self._read_from_stdin = False

    @property
    def input_cmd(self):
        return self._input_cmd

    def _set_stdin(self):
        self._read_from_stdin = True
        self.set_input_file(self.PIPE)

    @typed(command=IsType(ITJellyfishRemoteCommand))
    def set_local_stdin(self, command, capturing_ready_string=None):
        self._set_stdin()
        self._set_capturing_ready_string(capturing_ready_string)
        self._input_cmd = command.cmd

    @typed(command=IsType(ITJellyfishRemoteCommand))
    def set_remote_stdin(self, remote_ip, command,
                         username=secrets.MODULE_USERNAME, password=secrets.MODULE_PASSWORD,
                         capturing_ready_string='listening on'):
        self._set_stdin()
        self._set_capturing_ready_string(capturing_ready_string)
        args = {'remote_ip': remote_ip,
                'username': username,
                'password': password,
                'command': command.cmd}
        self._input_cmd = 'sshpass -p {password} ' \
                          'ssh -q ' \
                          '-o StrictHostKeyChecking=no ' \
                          '-o GlobalKnownHostsFile=/dev/null ' \
                          '-o UserKnownHostsFile=/dev/null ' \
                          '{username}@{remote_ip} ' \
                          '"{command}"'.format(**args)

    def _set_capturing_ready_string(self, capturing_ready_string):
        self._capturing_ready_string = capturing_ready_string if capturing_ready_string else ''

    def _get_cmd_with_stdin(self):
        return '{} | {}'.format(self._input_cmd, ' '.join(self.cmd))

    def start(self, stdout=None, stderr=None):
        if not self._read_from_stdin:
            return super(Tjellyfish, self).start(stdout, stderr)

        self._assert_process_not_in_started_state()
        self._handlers.create(stdout, stderr)
        self._process = subprocess.Popen(self._get_cmd_with_stdin(),
                                         shell=True,
                                         preexec_fn=os.setsid,
                                         stdout=self._handlers.stdout_write,
                                         stderr=self._handlers.stderr_write)
        self._capture_readiness_handler = self._handlers.stderr_read
        logger.debug('Tjellyfish started')

    def run_until_completion(self):
        if not self._read_from_stdin:
            return super(Tjellyfish, self).run_until_completion()

        return subprocess.check_output(self._get_cmd_with_stdin(),
                                       shell=True,
                                       stderr=subprocess.STDOUT)
